use crate::{java_runtime::{Rc,RefCell},cn::wps::{moss::{app::KmoBookApi::KmoBookApi,engine::linktb::{NameRecord::{NameRecord,NameRecordRef,review::name},LinkInfo::LinkInfo},xlsxr::{handler::WorkbookDelayHandler::WorkbookDelayHandler,util::UnifiedXmlReader::UnifiedXmlReader}},et::ss::formula::ptg::Ptg::{Ptg,PtgKind,serializePtgs}},org::apache::poi::ss::SpreadsheetVersion::SpreadsheetVersion};
use kfc::cn::wps::memor4j::KmoAtomStore::{KmoAtomStore,KmoAtomStoreTrait};
use serde_json::{json,Value};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn store<T>(f:impl FnOnce(&mut dyn KmoAtomStoreTrait)->T)->T{f(KmoAtomStore::sharedStore().as_mut().unwrap().as_mut())}
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IndexOutOfBoundsException","ArrayIndexOutOfBoundsException","IllegalStateException","RuntimeException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
fn make(n:&str,v:u16)->NameRecordRef{let mut r=NameRecord::NameRecord(SpreadsheetVersion::EXCEL2007);r.setNameText(n);r.setNameDefinition(vec![Ptg::base(PtgKind::Int(v))]);Rc::new(RefCell::new(r))}
fn info(h:&LinkInfo,a:&NameRecordRef)->Value{json!({"count":call(||h.getNamesCount()),"index":call(||h.indexOf(Some(a.clone()))),"names":call(||h.nameInfos().borrow().iter().map(|r|r.as_ref().map(|r|json!({"same":Rc::ptr_eq(a,r),"name":r.borrow().getNameText(),"def":call(||{let p=r.borrow_mut().getNameDefinition();{let encoded=serializePtgs(&crate::cn::wps::et::ss::formula::ptg::Ptg::ptgValues(&p));encoded.iter().map(|v|format!("{v:02x}")).collect::<String>()}})}))).collect::<Vec<_>>()),"undo":store(|s|s.canUndo()),"redo":store(|s|s.canRedo()),"started":store(|s|s.isAtomStarted())})}
fn transaction()->Value{
    KmoAtomStore::enable();KmoAtomStore::clearUp();store(|_|{});let h=LinkInfo::LinkInfo();let a=make("a",3);let b=make("b",5);h.addNameInfo(a.clone());let mut rows=vec![info(&h,&a)];
    h.nameInfos().borrow_mut().push(Some(b.clone()));rows.push(info(&h,&a));
    store(|s|s.start());h.addNameInfo(b.clone());rows.push(info(&h,&a));rows.push(json!(store(|s|s.commit())));rows.push(info(&h,&a));
    a.borrow_mut().setNameText("held-a");rows.push(info(&h,&a));store(|s|s.undo());rows.push(info(&h,&a));store(|s|s.redo());rows.push(info(&h,&a));
    store(|s|s.start());h.removeNameInfo(0);rows.push(info(&h,&a));rows.push(json!(store(|s|s.commit())));store(|s|s.undo());rows.push(info(&h,&a));store(|s|s.redo());rows.push(info(&h,&a));
    store(|s|s.start());rows.push(call(||{h.removeNameInfo__name(Some(a.clone()));Value::Null}));rows.push(json!(store(|s|s.commit())));rows.push(info(&h,&a));store(|s|s.undo());rows.push(info(&h,&a));
    let live=Rc::new(RefCell::new(vec![Some(a.clone())]));h.setNameInfos(Some(live.clone()),false);live.borrow_mut().push(Some(b));rows.push(info(&h,&a));store(|s|s.start());h.setNameInfos(Some(Rc::new(RefCell::new(vec![]))),true);rows.push(json!(store(|s|s.commit())));rows.push(info(&h,&a));store(|s|s.undo());rows.push(info(&h,&a));live.borrow_mut().clear();rows.push(info(&h,&a));store(|s|s.redo());rows.push(info(&h,&a));json!(rows)
}
fn copyFailures()->Value{let mut rows=vec![];for kind in 0..3{KmoAtomStore::enable();KmoAtomStore::clearUp();store(|_|{});let h=LinkInfo::LinkInfo();let a=make("anchor",7);let list=Rc::new(RefCell::new(vec![if kind==1{None}else{Some(a.clone())}]));if kind==2{a.borrow_mut().setFormula(None);}h.setNameInfos(if kind==0{None}else{Some(list)},false);store(|s|s.start());let mut o=json!({"add":call(||{h.addNameInfo(make("new",2));Value::Null}),"afterAdd":info(&h,&a),"again":call(||{h.addNameInfo(make("retry",4));Value::Null}),"afterAgain":info(&h,&a),"commit":store(|s|s.commit()),"afterCommit":info(&h,&a)});store(|s|s.undo());o["undo"]=info(&h,&a);store(|s|s.redo());o["redo"]=info(&h,&a);rows.push(o);}KmoAtomStore::clearUp();json!(rows)}
#[test]
fn original_android_linkinfo_transactions_and_delayed_names(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/name-pipeline-r0b47");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let transactions=transaction();let failures=copyFailures();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let mut rows=vec![];
    for text in input["xml"].as_array().unwrap(){let before=book.getLinkTable().borrow().getNumNames();let mut o=call(||{UnifiedXmlReader::read(&mut std::io::Cursor::new(text.as_str().unwrap().as_bytes()),Box::new(WorkbookDelayHandler::WorkbookDelayHandler(book.clone()))).unwrap();Value::Null});let mut added=vec![];for n in before..book.getLinkTable().borrow().getNumNames(){added.push(name(&mut book.getLinkTable().borrow().getNameRecord(n).unwrap().borrow_mut()));}o["added"]=json!(added);o["count"]=json!(book.getLinkTable().borrow().getNumNames());rows.push(o);}
    let actual=json!({"transactions":transactions,"copyFailures":failures,"xml":rows});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&java,"root");
}
